import type { ChoiceQuestion } from '../types'
import { PRINT } from './helpers'

// Second questions for each concept of a lesson test: same idea, different question.
// A test asks one question per concept; a retake swaps in a question you have not seen
// for every concept you got wrong. The first option is the correct one.
function alt(concept: string, question: string, options: string[], explain: string, code?: string): ChoiceQuestion {
  return { id: `${concept}-b`, concept, question, options, answer: 0, explain, code }
}

